 mpath=L.ROOT/'assets/research-20261105/acquisition.json';m=json.loads(mpath.read_text());r=m['derr-2012-main.html']
 if r.get('status')=='available':old=dict(r);r.update(status='failed',error='Content inspection: Checking your browser - reCAPTCHA; not article content',prior_transfer=old);L.atomic(mpath,json.dumps(m,indent=2))
 b=next(b for b in L.read('batches') if b['batch_id']=='B0007');b['completed_actions']+=['Added two EGNAS computational redesign families and explicit parent relationships.','Reviewed primary motor-ensemble chassis design via saved web-provider text; direct HTML response is a challenge, marked failed.','Hashed complete sharp-triangle ZIP member inventory without constructing molecular structures.'];b['after_counts']=L.counts();b['next_queue']=[k for k in b['input_keys'] if next(r for r in L.read('publication_reviews') if r['registry_key']==k)['review_stage']=='unreviewed'];b['validation']=[L.validate()];L.upsert('batches',b,'Save17 substantive source reviews and eight remaining rotating inputs')
